#include <stdlib.h>
#include <string.h>
#include <magick/api.h>

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                              MagickOffsetType PS_Offset, ssize_t PS_Size,
                              ExceptionInfo *exception) {
  Image *new_image = (Image *) NULL;
  ImageInfo *clone_info = (ImageInfo *) NULL;
  char filename[MaxTextLength];
  FILE *file = (FILE *) NULL;

  (void) GetPathComponent(image->filename, TailPath, filename, MaxTextLength);
  (void) CopyMagickString(filename, "ps:", MaxTextLength);
  (void) ConcatenateMagickString(filename, "ps", MaxTextLength);

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    goto cleanup;

  if ((file = fopen(filename, "wb")) == (FILE *) NULL)
    goto cleanup;

  if (WriteBlobFile(file, PS_Offset, PS_Size, image) != MagickTrue) {
    fclose(file);
    file = (FILE *) NULL;
    goto cleanup;
  }

  if (fclose(file) != 0)
    file = (FILE *) NULL;

  new_image = ReadImage(clone_info, filename, exception);
  if (new_image == (Image *) NULL)
    goto cleanup;

  if (image->previous == (Image *) NULL) {
    new_image->next = GetFirstImageInList(image);
    new_image->next->previous = new_image;
  }
  else {
    new_image->previous = image->previous;
    image->previous->next = new_image;
  }

  new_image->next = image;
  image->previous = new_image;

  *image = **GetLastImageInList(new_image);

cleanup:
  if (clone_info != (ImageInfo *) NULL)
    clone_info = DestroyImageInfo(clone_info);

  if (file != (FILE *) NULL)
    fclose(file);

  return (new_image != (Image *) NULL) ? new_image : image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                               MagickOffsetType PS_Offset, ssize_t PS_Size,
                               ExceptionInfo *exception) {
  Image *new_image;
  ImageInfo *clone_info;
  char filename[MaxTextLength];
  FILE *file;

  clone_info = CloneImageInfo(image_info);
  GetPathComponent(image->filename, filename);

  file = AcquireUniqueFileResource(filename);
  if (file == (FILE *) NULL) {
    ThrowBinaryException(FileOpenError, "Unable to create temporary file", filename);
  }

  (void) fwrite((void *) (image->pixels + PS_Offset), 1, (size_t) PS_Size, file);
  (void) fclose(file);

  if (IsBlobPS(filename) != MagickFalse) {
    new_image = ReadImage(clone_info, exception);
    if (new_image != (Image *) NULL) {
      (void) CloneImageAttributes(image, new_image);
      image = DestroyImageList(image);
      image = new_image;
    }
  }

  RelinquishResource(filename);
  return (image);
}

#include <stdio.h>
#include <stdlib.h>
#include "magick/api.h"

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception) {
  ImageInfo *clone_info = CloneImageInfo(image_info);
  Image *new_image = NULL;
  FILE *file = NULL;
  MagickBooleanType status;
  char filename[MagickPathExtent];

  GetPathComponent(image->filename,FileName,clone_info->filename);
  GetPathComponent(clone_info->filename,BaseName,filename);
  (void) FormatLocaleString(clone_info->filename,MagickPathExtent,"%s",filename);

  file = AcquireUniqueFileResource(clone_info->filename);
  if (file == (FILE *) NULL)
    ThrowBinaryException(FileOpenError,"Unable to create temporary file",clone_info->filename);

  if (PS_Size > 0) {
    size_t written = fwrite((void *) (image->blob + PS_Offset), sizeof(unsigned char), (size_t) PS_Size, file);
    if ((ssize_t) written != PS_Size) {
      RelinquishUniqueFileResource(clone_info->filename);
      return image;
    }
  }

  (void) fclose(file);

  clone_info = CloneImageInfo(clone_info);
  clone_info->number_scenes = 1;
  clone_info->scene = 0;
  clone_info->subimage = 1;
  clone_info->subrange = 1;

  new_image = ReadImage(clone_info, exception);
  if (new_image == (Image *) NULL) {
    RelinquishUniqueFileResource(clone_info->filename);
    return image;
  }

  (void) CopyImageAttributes(image, new_image);
  (void) CopyImageProfiles(image, new_image);
  (void) CopyImageProperties(image, new_image);

  DestroyImageInfo(clone_info);
  RelinquishUniqueFileResource(clone_info->filename);

  return new_image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                              MagickOffsetType PS_Offset, ssize_t PS_Size,
                              ExceptionInfo *exception) {
  Image
    *clone_image = (Image *) NULL,
    *new_image = (Image *) NULL;

  ImageInfo
    *clone_info;

  char
    filename[MaxTextLength];

  MagickBooleanType
    status;

  assert(image != (Image *) NULL);
  assert(image->signature == MagickSignature);
  assert(image_info != (ImageInfo *) NULL);
  assert(exception != (ExceptionInfo *) NULL);
  (void) AcquireUniqueFilename(filename);
  clone_info = (ImageInfo *) CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    {
      if (exception != (ExceptionInfo *) NULL)
        (void) ThrowMagickException(exception,GetMagickModule(),ResourceLimitError,
          "MemoryAllocationFailed","unable to clone image info");
      return(image);
    }
  status=WriteBlobFile(filename,clone_info,PS_Offset,PS_Size,image,exception);
  if (status == MagickFalse)
    {
      clone_info=DestroyImageInfo(clone_info);
      return(image);
    }
  clone_info=DestroyImageInfo(clone_info);
  clone_image=ReadImage(image_info,filename,exception);
  if (clone_image == (Image *) NULL)
    return(image);
  new_image=CloneImage(image,0,0,MagickTrue,exception);
  if (new_image == (Image *) NULL)
    {
      clone_image=DestroyImageList(clone_image);
      return(image);
    }
  (void) CopyImageAttributes(new_image,clone_image);
  (void) CopyImageProfiles(new_image,clone_image);
  clone_image=DestroyImageList(clone_image);
  image=DestroyImageList(image);
  return(new_image);
}

#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                              MagickOffsetType PS_Offset, ssize_t PS_Size,
                              ExceptionInfo *exception) {
    Image *new_image = NULL;
    ImageInfo *clone_info = CloneImageInfo(image_info);
    char filename[MagickPathExtent];

    GetPathComponent(image->filename, Filename, filename, MagickPathExtent);
    (void) CopyMagickString(clone_info->filename, filename, MagickPathExtent);

    // Write Postscript data to a temporary file
    FILE *file = fopen(clone_info->filename, "wb");
    if (!file) {
        ThrowFileException(exception, FileOpenError, CannotOpenFile, clone_info->filename);
        return image;
    }

    if (fwrite((void *) (image->pixels + PS_Offset), sizeof(PixelPacket), PS_Size, file) != (size_t) PS_Size) {
        fclose(file);
        return image;
    }

    fclose(file);

    // Check file format using magic numbers
    new_image = ReadImage(clone_info, exception);
    if (!new_image) {
        return image;
    }

    // Replace the original image with the new one
    (void) CloneImageAttributes(image, new_image);
    (void) CloneImageProfiles(image, new_image);
    DestroyImage(new_image);

    // Clean up resources
    clone_info = DestroyImageInfo(clone_info);

    return image;
}
